CREATE TABLE IF NOT EXISTS organizations(id text PRIMARY KEY,name text NOT NULL,demo boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),email text UNIQUE NOT NULL,name text NOT NULL,password_hash text,role text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS sessions(sid text PRIMARY KEY,data jsonb NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS customers(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),code text NOT NULL,name text NOT NULL,name_zh text,UNIQUE(org_id,code));
CREATE TABLE IF NOT EXISTS destinations(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),customer_id text REFERENCES customers(id),name text NOT NULL,address text,verified boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS products(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),sku text NOT NULL,name text NOT NULL,name_zh text,profile text NOT NULL,unit text NOT NULL,pack_size numeric(18,6),pack_verified boolean NOT NULL DEFAULT false,handling text,UNIQUE(org_id,sku),CHECK(pack_size IS NULL OR pack_size>0));
CREATE TABLE IF NOT EXISTS lots(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),product_id text NOT NULL REFERENCES products(id),reference text NOT NULL,expires_on date,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS locations(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),code text NOT NULL,name text NOT NULL,kind text NOT NULL,capacity numeric,restrictions text,UNIQUE(org_id,code));
CREATE TABLE IF NOT EXISTS pallets(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),code text NOT NULL,location_id text NOT NULL REFERENCES locations(id),version integer NOT NULL DEFAULT 1,manifest_revision integer NOT NULL DEFAULT 1,checked_revision integer,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,code));
CREATE TABLE IF NOT EXISTS boxes(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),code text NOT NULL,customer_id text REFERENCES customers(id),location_id text REFERENCES locations(id),pallet_id text REFERENCES pallets(id),source_label text,condition text NOT NULL DEFAULT 'good',status text NOT NULL DEFAULT 'unconfirmed',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,code),CHECK((pallet_id IS NULL AND location_id IS NOT NULL) OR (pallet_id IS NOT NULL AND location_id IS NULL)));
CREATE TABLE IF NOT EXISTS contents(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),box_id text NOT NULL REFERENCES boxes(id),product_id text NOT NULL REFERENCES products(id),lot_id text REFERENCES lots(id),quantity numeric(18,6),unit text NOT NULL,verified boolean NOT NULL DEFAULT false,source text NOT NULL DEFAULT 'manual',CHECK(quantity IS NULL OR quantity>0),CHECK(NOT verified OR quantity IS NOT NULL));
CREATE TABLE IF NOT EXISTS orders(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),code text NOT NULL,customer_id text NOT NULL REFERENCES customers(id),destination_id text NOT NULL REFERENCES destinations(id),status text NOT NULL DEFAULT 'open',version integer NOT NULL DEFAULT 1,partial_approved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,code));
CREATE TABLE IF NOT EXISTS order_lines(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),order_id text NOT NULL REFERENCES orders(id),product_id text NOT NULL REFERENCES products(id),quantity numeric(18,6) NOT NULL,unit text NOT NULL,CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS allocations(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),order_id text NOT NULL REFERENCES orders(id),order_line_id text NOT NULL REFERENCES order_lines(id),box_id text NOT NULL REFERENCES boxes(id),contents_id text NOT NULL REFERENCES contents(id),quantity numeric(18,6) NOT NULL,CHECK(quantity>0),UNIQUE(order_line_id,contents_id));
CREATE TABLE IF NOT EXISTS preparations(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),business_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS preparation_orders(preparation_id text NOT NULL REFERENCES preparations(id),order_id text NOT NULL REFERENCES orders(id),stage text NOT NULL DEFAULT 'selected',staging_location_id text REFERENCES locations(id),checked boolean NOT NULL DEFAULT false,PRIMARY KEY(preparation_id,order_id),UNIQUE(order_id));
CREATE TABLE IF NOT EXISTS trips(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),code text NOT NULL,business_date date NOT NULL,driver_id text REFERENCES users(id),vehicle text,status text NOT NULL DEFAULT 'planned',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,code));
CREATE TABLE IF NOT EXISTS stops(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),trip_id text NOT NULL REFERENCES trips(id),destination_id text NOT NULL REFERENCES destinations(id),position integer NOT NULL,UNIQUE(trip_id,position));
CREATE TABLE IF NOT EXISTS shipments(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),order_id text NOT NULL REFERENCES orders(id),destination_id text NOT NULL REFERENCES destinations(id),trip_id text REFERENCES trips(id),stop_id text REFERENCES stops(id),status text NOT NULL DEFAULT 'ready',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shipment_lines(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),shipment_id text NOT NULL REFERENCES shipments(id),box_id text NOT NULL REFERENCES boxes(id),product_id text NOT NULL REFERENCES products(id),quantity numeric(18,6) NOT NULL,unit text NOT NULL,loaded boolean NOT NULL DEFAULT false,delivered numeric(18,6) NOT NULL DEFAULT 0,returned numeric(18,6) NOT NULL DEFAULT 0,CHECK(delivered>=0 AND returned>=0 AND delivered+returned<=quantity));
CREATE TABLE IF NOT EXISTS documents(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),box_id text REFERENCES boxes(id),name text NOT NULL,storage_key text NOT NULL,mime text NOT NULL,sha256 text NOT NULL,size integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS issues(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),box_id text REFERENCES boxes(id),kind text NOT NULL,note text NOT NULL,status text NOT NULL DEFAULT 'open',resolution text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory_events(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),actor_id text NOT NULL REFERENCES users(id),entity_id text NOT NULL,kind text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS operations(org_id text NOT NULL REFERENCES organizations(id),command text NOT NULL,operation_id text NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,command,operation_id));
CREATE TABLE IF NOT EXISTS jobs(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),actor_id text NOT NULL REFERENCES users(id),kind text NOT NULL,status text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,payload jsonb NOT NULL DEFAULT '{}',result jsonb,error text,available_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tracking_marks(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),symbol text NOT NULL,meaning text,scope text NOT NULL,version integer NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS boxes_org_page ON boxes(org_id,created_at,id);
CREATE INDEX IF NOT EXISTS events_entity ON inventory_events(org_id,entity_id,created_at,id);
CREATE INDEX IF NOT EXISTS allocations_box ON allocations(box_id);
CREATE OR REPLACE FUNCTION protect_business_events() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'Business events are immutable'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS immutable_events ON inventory_events;
CREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON inventory_events FOR EACH ROW EXECUTE FUNCTION protect_business_events();
